int handle_ipv4_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh, struct netlink_ext_ack *extack)
{
    struct rtmsg *rtm = nlmsg_data(nlh);
    struct net *net = sock_net(in_skb->sk);
    struct net_device *dev = NULL;
    struct iphdr *iph;
    struct rt_key {
        __be32 daddr;
        __be32 saddr;
        u8 tos;
        u32 table;
    } key;
    struct sk_buff *skb;
    struct nlmsghdr *resp_nlh;
    struct rtmsg *resp_rtm;
    int err;

    if (nlh->nlmsg_len < NLMSG_HDRLEN + sizeof(*rtm))
        return -EINVAL;

    key.daddr = rtm->rtm_dst;
    key.saddr = rtm->rtm_src;
    key.tos = rtm->rtm_tos;
    key.table = rtm->rtm_table;

    skb = alloc_skb(NLMSG_GOODSIZE, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    skb_reserve(skb, MAX_HEADER);

    resp_nlh = nlmsg_put(skb, NETLINK_CB(in_skb).portid, nlh->nlmsg_seq, RTM_NEWROUTE, sizeof(*resp_rtm), NLM_F_MULTI);
    if (!resp_nlh) {
        kfree_skb(skb);
        return -EMSGSIZE;
    }

    resp_rtm = nlmsg_data(resp_nlh);
    *resp_rtm = *rtm;

    if (key.daddr) {
        dev = dev_get_by_index(net, rtm->rtm_oif);
        if (!dev) {
            err = -ENODEV;
            goto error;
        }
    }

    iph = ip_hdr(skb);
    iph->daddr = key.daddr;
    iph->saddr = key.saddr;
    iph->tos = key.tos;

    iph->tot_len = htons(skb->len);
    iph->check = 0;
    iph->check = ip_fast_csum(iph, iph->ihl);

    if (dev) {
        skb->dev = dev;
        skb->protocol = htons(ETH_P_IP);
        skb_reset_network_header(skb);
        skb->network_header = skb->data;
    }

    if (nlh->nlmsg_flags & NLM_F_ACK)
        nlh->nlmsg_flags |= NLM_F_ACK;

    netlink_unicast(in_skb->sk->sk_net, skb, NETLINK_CB(in_skb).portid, MSG_DONTWAIT);

    return 0;

error:
    if (dev)
        dev_put(dev);
    kfree_skb(skb);
    return err;
}

int handle_ipv4_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh,
                           struct netlink_ext_ack *extack)
{
    struct ip_rt_info {
        __be32 src;
        __be32 dst;
        int ifindex;
        uid_t uid;
        unsigned int flags;
    } route_info;
    struct sk_buff *skb = NULL;
    struct nlmsghdr *reply;
    struct rtmsg *rtm;
    int ret = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN + sizeof(*rtm))
        goto error;

    rtm = nlmsg_data(nlh);
    if (rtm->rtm_family != AF_INET)
        goto error;

    route_info.src = rtm->rtm_src;
    route_info.dst = rtm->rtm_dst;
    route_info.ifindex = rtm->rtm_oif;
    route_info.uid = current_uid().val;
    route_info.flags = rtm->rtm_flags;

    skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
    if (!skb)
        goto error;

    reply = __nlmsg_put(skb, 0, 0, NLMSG_DONE, 0, 0);
    if (!reply)
        goto error;

    ret = ip_route_output_key(net, &route, &route_info.dst, &route_info.src,
                              0, route_info.ifindex, 0, 0, 0, 0);
    if (ret < 0)
        goto error;

    ret = ip_route_input(&route, route_info.dst, route_info.src, 0,
                         route_info.ifindex, 0);
    if (ret < 0)
        goto error;

    reply->nlmsg_type = RTM_NEWROUTE;
    reply->nlmsg_flags = NLM_F_MULTI;
    rtm = nlmsg_data(reply);
    rtm->rtm_family = AF_INET;
    rtm->rtm_dst_len = 32;
    rtm->rtm_src_len = 32;
    rtm->rtm_tos = 0;
    rtm->rtm_table = RT_TABLE_MAIN;
    rtm->rtm_scope = RT_SCOPE_UNIVERSE;
    rtm->rtm_protocol = RTPROT_KERNEL;
    rtm->rtm_type = RTN_UNICAST;
    rtm->rtm_flags = route_info.flags;

    ret = 0;

error:
    if (ret < 0 && extack) {
        NL_SET_ERR_MSG(extack, "Failed to handle IPv4 route information");
    }
    if (skb)
        kfree_skb(skb);
    return ret;
}

int handle_ip_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh, struct netlink_ext_ack *extack) {
    struct ip_rt_info *rt_info;
    struct sk_buff *skb;
    int ret = -EINVAL;

    if (!in_skb || !nlh)
        return ret;

    skb = alloc_skb(128, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    rt_info = skb_put(skb, sizeof(*rt_info));
    if (!rt_info) {
        kfree_skb(skb);
        return -ENOMEM;
    }

    memset(rt_info, 0, sizeof(*rt_info));

    rt_info->src = 0;
    rt_info->dst = 0;
    rt_info->ifindex = 0;
    rt_info->flags = 0;

    if (nlh->nlmsg_flags & NLM_F_CREATE)
        rt_info->flags |= RT_INFO_F_CREATE;

    if (nlh->nlmsg_flags & NLM_F_REPLACE)
        rt_info->flags |= RT_INFO_F_REPLACE;

    ret = 0;
    netlink_unicast(in_skb->sk->sk_net, skb, NETLINK_CB(in_skb).portid, 0);
    return ret;
}

